const P=new URLSearchParams(location.search),en=P.get('lang')==='en',L=en?'en':'ko';
const T=(k,e)=>String((en?e:k)??'').replace(/\.(?=\s|<|$)/g,''),E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const U=(p,o={})=>`${p}.html?${new URLSearchParams({...o,lang:L})}`;
const route=location.pathname.split('/').pop().replace('.html','')||'index';
const nav=[['business','기술과 솔루션','Expertise'],['research','연구와 성과','Research'],['ax-platform','AX Platform','AX Platform'],['company','GeoSR 소개','About GeoSR'],['news','소식','News']];
const A=(href,k,e,cl='link')=>{const external=/^https?:\/\//.test(href),action=/^(mailto:|tel:)/.test(href),contextual=/plain-arrow|ink-link|field-link|pill-link/.test(cl);return `<a class="${cl}" href="${href}"${external?' target="_blank" rel="noopener"':''}>${T(k,e)}${external||action||contextual?' <span>↗</span>':''}</a>`};
const img=(src,alt,concept=false,cl='')=>`<figure class="visual ${cl}"><img src="assets/${src}" alt="${E(alt)}" loading="lazy">${concept?`<figcaption>${T('영상 가안 · IMAGEGEN','FILM CONCEPT · IMAGEGEN')}</figcaption>`:''}</figure>`;
const filmSlot=(id,label,description='')=>`<figure class="visual route-film-frame" data-production-slot="${E(id)}" data-film-slot="${E(id)}" data-motion-mode="detail-focus" aria-label="${E(label)}"><div class="route-film-fallback"><span>${T('콘텐츠 제작 준비 중','CONTENT IN PREPARATION')}</span><strong>${E(label)}</strong>${description?`<p>${E(description)}</p>`:''}</div><figcaption>${T('향후 MP4·GIF 삽입 영역','FUTURE MP4/GIF SLOT')}</figcaption></figure>`;
