function head(){return `<a class="skip" href="#main">${T('본문으로 이동','Skip to content')}</a><header class="${route==='index'?'':'solid'}"><a class="brand" href="${U('index')}"><img src="assets/logo.png" alt="GeoSR"></a><nav id="primary-navigation" aria-label="${T('주 메뉴','Main navigation')}">${nav.map(([r,k,e])=>`<a href="${U(r)}" ${route===r?'aria-current="page"':''}>${T(k,e)}</a>${r==='ax-platform'?'<a href="https://www.geo-dap.com/" target="_blank" rel="noopener">GeoDAP ↗</a>':''}` ).join('')}</nav><div class="header-actions"><button id="language" aria-label="${T('영어로 전환','Switch to Korean')}">${T('EN','KR')}</button><a href="${U('contact')}" class="contact-link">${T('문의하기','Contact')}</a><button id="menu" aria-controls="primary-navigation" aria-expanded="false" aria-label="${T('메뉴 열기','Open menu')}">☰</button></div></header>`}
function foot(){return modernFooter()}

function title(n,k,e,dk='',de=''){return `<section class="page-title"><p class="eyebrow">${n}</p><h1>${T(k,e)}</h1><p>${T(dk,de)}</p></section>`}
function rows(items){return items.map(p=>`<a class="record ${p[5]?'mock-record':''}" href="${U(['notice','press','newsletter'].includes(p[1])?'news':'research',{id:p[0],board:P.get('board')||'all',q:P.get('q')||''})}"><span class="record-type">${T(...types.find(x=>x[0]===p[1]).slice(1))}</span><h3>${p[5]?`<em class="badge">${T('목업','DEMO')}</em> `:''}${E(T(p[3],p[4]))}</h3><time>${p[2]}</time><span>↗</span></a>`).join('')}
function business(){const id=Number(P.get('id'));if(id){const x=tech.find(v=>v.id===id);return `${title('TECHNOLOGY',x?.k||'기술 상세 목업',x?.e||'Technology detail',x?.dk||'상세 콘텐츠가 들어갈 자리입니다',x?.de||'A reserved layout for this technology.')}<section class="section detail">${x?`${img(x.image,T(x.k,x.e),!x.source,'source-image')}<div class="detail-split"><h2>${T('기술 개요','Overview')}</h2><div><p class="lead">${T(x.dk,x.de)}</p><p>${x.source?T('GeoSR 공식 홈페이지에 게시된 무인선 사진입니다','Original uncrewed vessel photograph published by GeoSR'):T('영상 콘셉트 이미지입니다 · 실제 관측값이나 분석 결과가 아닙니다','A visual concept for the technology film · not verified observations or analysis results')}</p></div></div><div class="detail-split"><h2>${T('관련 자료','Related resources')}</h2><div>${rows(posts.filter(p=>p[1]==='research'))}</div></div>`:`<div class="empty"><span class="badge">${T('목업','DEMO')}</span><h2>${T('소개 · 방법 · 결과 · 관련 자료','Overview · Methods · Results · Resources')}</h2><p>${T('전체 자료를 이관하지 않고 상세 페이지의 형태를 보존한 영역입니다','The detail-page structure is preserved without migrating the full archive.')}</p></div>`}${A(U('business'),'전체 기술로 돌아가기','Back to expertise')}</section>`};return `${title('OUR EXPERTISE','해양·환경 분야의<br>주요 기술과 솔루션','Connected disciplines.<br>A broader answer.','관측·분석·모델·AI·위성·시스템을 연결하는 GeoSR의 전문성','GeoSR expertise across observation, analysis, modelling, AI, satellite imagery and systems.')}<section class="section technology-hub">${disciplines.map((d,i)=>`<a class="discipline-row" href="${(d[7]===15?U('equipment',{category:'lab'}):U('business',{id:d[7]}))}"><div><p class="eyebrow">0${i+1} / ${d[1].toUpperCase()}</p><h2>${T(d[2],d[3])}</h2><p>${T(d[4],d[5])}</p><span class="link">${T(d[0],d[1])} ↗</span></div>${d[6]?img(d[6],T(d[0],d[1]),d[8]):filmSlot('business-environment',T(d[2],d[3]),T('수질·퇴적물 분석과 생태 조사를 위한 대표 장면을 준비 중입니다','A representative scene for water, sediment and ecological analysis is in preparation.'))}</a>`).join('')}<details class="legacy-index"><summary>${T('전체 업무·기술 분야 보기','Browse the complete technology index')}</summary><p>${T('기존 기술 명칭으로 정리한 전체 목록입니다. 대표 상세 3개를 제외한 항목은 목업 페이지로 연결됩니다.','Original technology names are preserved for reference. Beyond three representative pages, details are placeholders.')}</p><div id="tech-index"></div></details><div class="quick-links">${A('http://usv.co.kr','무인선 전문 사이트','USV website')}${A('https://e-navigation.co.kr','전자해도 전문 사이트','Electronic navigation')}${A(U('equipment'),'관측·장비 보기','Field capabilities')}</div></section>`}
function archive(){const news=route==='news',allowed=news?['notice','press','newsletter']:['business','research','academic'];const id=P.get('id');if(id){const p=posts.find(v=>v[0]===id&&allowed.includes(v[1]));return `<section class="article">${A(U(route,{board:P.get('board')||'all',q:P.get('q')||''}),'목록으로','Back to list')}<p class="eyebrow">${p?T(...types.find(v=>v[0]===p[1]).slice(1)):'NOT FOUND'}</p><h1>${p?E(T(p[3],p[4])):T('자료를 찾을 수 없습니다','Content not found.')}</h1>${p?`<div class="article-meta">GeoSR <time>${p[2]}</time>${p[5]?`<span class="badge">${T('목업','DEMO')}</span>`:''}</div><div class="article-body"><p>${p[5]?T('본문·이미지·첨부를 추가할 예시 화면입니다. 실제 게시글은 아닙니다.','A placeholder for article text, images and attachments. This is not a real article.'):T('기존 홈페이지에서 확인한 글의 제목과 날짜입니다. 본문은 대표 항목만 연결했으며, 전체 자료는 아직 이관하지 않았습니다.','The title and date are sourced from the existing website. This prototype connects representative records without migrating every article in full.')}</p>${p[0]==='notice-3091'?`<a class="download" href="assets/notice.pdf" target="_blank" rel="noopener">↓ PDF · ${T('해양수산 신기술 인증 공고 원문','Original certification notice (Korean)')}</a>`:`<div class="empty">${T('본문·첨부 자료 목업 영역','Article and attachment placeholder')}</div>`}</div>`:''}</section>`};const board=P.get('board')||'all',q=P.get('q')||'',list=posts.filter(p=>allowed.includes(p[1])&&(board==='all'||p[1]===board)&&(p[3]+p[4]).toLowerCase().includes(q.toLowerCase()));return `${title(news?'NEWSROOM':'RESEARCH & IMPACT',news?'GeoSR 소식':'연구개발 및<br>주요 수행실적',news?'Today at GeoSR.<br>Tomorrow’s possibilities.':'Research accumulates.<br>Possibilities expand.',news?'공지, 언론 소식, 뉴스레터':'현장에서 시작해 연구와 학술로 이어지는 기록',news?'Notices, media coverage and newsletters.':'Work connecting field projects, research and publications.')}<section class="section archive"><div class="filters">${[['all','전체','All'],...types.filter(v=>allowed.includes(v[0]))].map(v=>`<a class="${board===v[0]?'active':''}" href="${U(route,{board:v[0],q})}">${T(v[1],v[2])}</a>`).join('')}</div><form class="search" action="${route}.html"><input name="lang" type="hidden" value="${L}"><input name="board" type="hidden" value="${E(board)}"><label for="q">${T('자료 검색','Search resources')}</label><div><input id="q" name="q" placeholder="${T('제목으로 검색','Search by title')}" value="${E(q)}"><button>${T('검색','Search')}</button></div></form><p class="result-count">${T('목업에 포함된 항목','Prototype entries')} ${list.length} · ${T('유형별 실제 자료 1건과 목업 1건','One source entry + one placeholder per category')}</p><div class="records">${list.length?rows(list):`<div class="empty"><h2>${T('검색 결과가 없습니다','No results found.')}</h2>${A(U(route),'검색 초기화','Clear search')}</div>`}</div></section>`}
const eq=[['1937','survey','스테레오 카메라 수중 드론','Stereo-camera underwater drone','BlueROV2','equipment-rov.png'],['1176','lab','유도결합플라즈마 질량분석기','Inductively coupled plasma mass spectrometer','ICP-MS · iCAP-RQ','equipment-icp.png'],['1938','vessel','해누리호','Haenuri survey vessel','Haenuri','equipment-vessel.jpg']];
function equipment(){const c=P.get('category')||'all';return `${title('FIELD CAPABILITIES','관측·분석 장비<br>및 조사선','Field capabilities.<br>Supporting the science.','관측·실험·선박의 대표 장비를 소개합니다','Representative survey equipment, laboratory instruments and vessels.')}<section class="section"><div class="filters">${[['all','전체','All'],['survey','조사','Survey'],['lab','실험','Laboratory'],['vessel','선박','Vessels']].map(v=>`<a class="${c===v[0]?'active':''}" href="${U('equipment',{category:v[0]})}">${T(v[1],v[2])}</a>`).join('')}</div><div class="equipment-grid">${eq.filter(v=>c==='all'||c===v[1]).map(v=>`<article>${img(v[5],T(v[2],v[3]))}<p class="eyebrow">${v[4]}</p><h2>${T(v[2],v[3])}</h2><details><summary>${T('장비 정보','Equipment information')}</summary><p>${v[4]}</p><p>${T('기존 홈페이지 소개 항목입니다 상세 제원은 원자료를 확인한 뒤 추가할 예정입니다.','An entry from the existing website. Detailed specifications are reserved for verified source data.')}</p></details></article>`).join('')}</div></section>`}
